const express = require('express');
const bodyParser = require('body-parser');
const http = require('http');
const { Server } = require('socket.io');

const app = express();
const server = http.createServer(app); 
const io = new Server(server, {
    cors: { origin: "*" } 
});

app.use(bodyParser.json());

const PORT = 25580;
let receivedLogs = [];

// Socket ühenduse haldus
io.on('connection', (socket) => {
    console.log('Äpp ühendus terminaliga:', socket.id);
    
    // Kui äpp ühendub, saada talle kohe olemasolevad viimased logid
    socket.emit('logs_history', receivedLogs);

    // Kuulame terminalist tulevaid käske
    socket.on('execute_command', (command) => {
        console.log(`Command received: ${command}`);
        // SIIN: Saaksid käsu edasi saata DatabaseService-ile või täita süsteemis
        
        // Vastame äpile, et käsk võeti vastu
        const responseLog = { 
            message: `Command '${command}' executed.`, 
            receivedAt: new Date().toISOString(),
            type: 'system' 
        };
        io.emit('logs', responseLog); 
    });
});

app.post('/log', (req, res) => {
    const incomingLog = req.body;
    incomingLog.receivedAt = new Date().toISOString();
    
    receivedLogs.push(incomingLog);
    if (receivedLogs.length > 50) receivedLogs.shift();

    // --- KRITIILINE OSA: Saada logi kohe läbi socketi äppi ---
    io.emit('logs', incomingLog); 

    console.log('Logi saadetud äppi:', incomingLog.message);
    res.status(200).send({ message: 'Log received and broadcasted' });
});

server.listen(PORT, '0.0.0.0', () => {
    console.log(`Gateway & Socket running on port ${PORT}`);
});